INSERT INTO appr.Appraisal (AppraisalId, SeafarerId, AppraisalYear, RankCode, VesselId, Stage, Achievements, Challenges, SupportWanted, Strengths, Improvements, RehireRecommendation, PromotionReadiness, AppraiserComment, SeafarerAgrees, SeafarerComment, CountersignComment, OfficeDecision, PromotionApproved, OfficeRemarks, UpdatedOn) VALUES
('A2026-V1-MST','V1-MST',2026,'MST','V1','Self',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-01-25'),
('A2026-V1-CO','V1-CO',2026,'CO','V1','Appraiser',N'Completed all planned maintenance in my area and helped the dry-dock team with the hull survey.',N'Spare parts arrived late for the purifier overhaul.',N'More time with the Chief Officer on cargo calculations.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-07-03'),
('A2026-V1-2O','V1-2O',2026,'2O','V1','Self',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-01-21'),
('A2026-V1-3O','V1-3O',2026,'3O','V1','Appraiser',N'Led the drill programme after the PSC visit and closed every action within a week.',N'The new ECDIS software took time to learn.',N'More time with the Chief Officer on cargo calculations.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-08-05'),
('A2026-V1-CE','V1-CE',2026,'CE','V1','Reviewer',N'Finished all CBTs and started my next-rank familiarisation.',N'Short port stays made it hard to finish maintenance on time.',N'More time with the Chief Officer on cargo calculations.',N'Strong safety awareness; stops the job when something is wrong.',N'Keep PMS entries up to date the same day.',N'Recommended',N'NotApplicable',NULL,0,N'I believe the Safety rating does not reflect the drills I led after the PSC visit.',NULL,NULL,0,NULL,'2026-09-25'),
('A2026-V1-2E','V1-2E',2026,'2E','V1','Ack',N'Led the drill programme after the PSC visit and closed every action within a week.',N'Two crew changes in one month meant extra training of new joiners.',N'More time with the Chief Officer on cargo calculations.',N'Strong safety awareness; stops the job when something is wrong.',N'Take more ownership of training juniors.',N'Recommended',N'ReadyNextYear',NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-09-05'),
('A2026-V1-3E','V1-3E',2026,'3E','V1','Done',N'Completed all planned maintenance in my area and helped the dry-dock team with the hull survey.',N'Spare parts arrived late for the purifier overhaul.',N'Hands-on training on the new purifier.',N'Thorough with paperwork and records.',N'Take more ownership of training juniors.',N'WithReservations',N'NotYetReady',NULL,1,NULL,NULL,N'Approved',0,NULL,'2026-09-30'),
('A2026-V1-4E','V1-4E',2026,'4E','V1','Office',N'Kept my area clean and organised; no findings in the internal audit.',N'Two crew changes in one month meant extra training of new joiners.',N'Hands-on training on the new purifier.',N'Strong safety awareness; stops the job when something is wrong.',N'Keep PMS entries up to date the same day.',N'Recommended',N'NotYetReady',NULL,1,NULL,NULL,NULL,0,NULL,'2026-09-28'),
('A2026-V1-ETO','V1-ETO',2026,'ETO','V1','Ack',N'Completed all planned maintenance in my area and helped the dry-dock team with the hull survey.',N'Bad weather in the Bay of Bengal delayed deck painting.',N'Leadership course before my next contract.',N'Technically sound and quick to learn.',N'Plan the day''s work earlier and report delays sooner.',N'Recommended',N'NotApplicable',NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-09-13'),
('A2026-V1-DCD','V1-DCD',2026,'DCD','V1','Ack',N'Completed all planned maintenance in my area and helped the dry-dock team with the hull survey.',N'Bad weather in the Bay of Bengal delayed deck painting.',N'Guidance on preparing for my next-rank exam.',N'Strong safety awareness; stops the job when something is wrong.',N'Take more ownership of training juniors.',N'Recommended',N'ReadyNextYear',NULL,NULL,NULL,NULL,NULL,0,NULL,'2026-09-15'),
('A2026-V1-BSN','V1-BSN',2026,'BSN','V1','Reviewer',N'Kept my area clean and organised; no findings in the internal audit.',N'Spare parts arrived late for the purifier overhaul.',N'Guidance on preparing for my next-rank exam.',N'Calm under pressure and dependable on watch.',N'Improve accuracy of rest-hour records.',N'Recommended',N'NotApplicable',NULL,1,NULL,NULL,NULL,0,NULL,'2026-09-26'),
